class Config:
    def __init__(self):
        self._data: dict[str, dict[str, str]] = {}

    def parse_line(self, line: str) -> None:
        line = line.rstrip()  # bug: should be strip() to remove leading whitespace too
        if not line or line.startswith('#'):
            return
        if line.startswith('[') and line.endswith(']'):
            self._current_section = line[1:-1]
            if self._current_section not in self._data:
                self._data[self._current_section] = {}
        elif '=' in line:
            key, _, value = line.partition('=')
            section = getattr(self, '_current_section', 'DEFAULT')
            self._data.setdefault(section, {})[key.strip()] = value.strip()

    def parse(self, text: str) -> None:
        self._current_section = 'DEFAULT'
        self._data.setdefault('DEFAULT', {})
        for line in text.splitlines():
            self.parse_line(line)

    def get(self, section: str, key: str, default: str = '') -> str:
        return self._data.get(section, {}).get(key) or default  # bug: returns default if value is falsy (e.g., empty string); should use explicit None check

    def set(self, section: str, key: str, value: str) -> None:
        # bug: does not create section if it doesn't exist
        self._data[section][key] = value
